namespace Warehouse;

public sealed class InventoryTracker
{
    public int GetStockLevel(string sku) => throw new NotImplementedException();
    public void AddStock(string sku, int quantity) => throw new NotImplementedException();
    public bool NeedsReorder(string sku) => throw new NotImplementedException();
}

arguments.new_str:
namespace Warehouse;

public sealed class InventoryTracker
{
    private readonly Dictionary<string, int> _stock = new();
    private readonly Dictionary<string, int> _reorderThresholds = new();
    private readonly Dictionary<string, string> _skuWarehouse = new();

    public int ReorderThreshold { get; set; } = 10;

    public int GetStockLevel(string sku)
    {
        ArgumentException.ThrowIfNullOrEmpty(sku);
        return _stock.TryGetValue(sku, out var level) ? level : 0;
    }

    public void AddStock(string sku, int quantity)
    {
        ArgumentException.ThrowIfNullOrEmpty(sku);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);

        _stock[sku] = GetStockLevel(sku) + quantity;
    }

    public void RemoveStock(string sku, int quantity)
    {
        ArgumentException.ThrowIfNullOrEmpty(sku);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);

        var current = GetStockLevel(sku);
        if (quantity > current)
            throw new InvalidOperationException($"Insufficient stock for '{sku}'. Available: {current}, Requested: {quantity}");

        _stock[sku] = current - quantity;
    }

    public bool NeedsReorder(string sku)
    {
        ArgumentException.ThrowIfNullOrEmpty(sku);
        var threshold = _reorderThresholds.TryGetValue(sku, out var t) ? t : ReorderThreshold;
        return GetStockLevel(sku) <= threshold;
    }

    public void SetReorderThreshold(string sku, int threshold)
    {
        ArgumentException.ThrowIfNullOrEmpty(sku);
        ArgumentOutOfRangeException.ThrowIfNegative(threshold);
        _reorderThresholds[sku] = threshold;
    }

    public void AssignWarehouse(string sku, string warehouseId)
    {
        ArgumentException.ThrowIfNullOrEmpty(sku);
        ArgumentException.ThrowIfNullOrEmpty(warehouseId);
        _skuWarehouse[sku] = warehouseId;
    }

    public string? GetWarehouse(string sku)
    {
        ArgumentException.ThrowIfNullOrEmpty(sku);
        return _skuWarehouse.TryGetValue(sku, out var wh) ? wh : null;
    }

    public void TransferStock(string sku, int quantity, string fromWarehouse, string toWarehouse)
    {
        ArgumentException.ThrowIfNullOrEmpty(sku);
        ArgumentException.ThrowIfNullOrEmpty(fromWarehouse);
        ArgumentException.ThrowIfNullOrEmpty(toWarehouse);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);

        if (fromWarehouse == toWarehouse)
            throw new InvalidOperationException("Source and destination warehouses must differ.");

        var currentWarehouse = GetWarehouse(sku);
        if (currentWarehouse != fromWarehouse)
            throw new InvalidOperationException($"SKU '{sku}' is not assigned to warehouse '{fromWarehouse}'.");

        RemoveStock(sku, quantity);
        _skuWarehouse[sku] = toWarehouse;
        AddStock(sku, GetStockLevel(sku) + quantity == 0 ? quantity : 0);
        // Simplified: transfer moves all requested quantity and reassigns warehouse
        _stock[sku] = GetStockLevel(sku) + quantity;
        _skuWarehouse[sku] = toWarehouse;
    }
}

