using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public sealed class StockLevelTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN-001"));
    }

    [TestMethod]
    public void AddStock_SingleAdd_IncreasesLevel()
    {
        _tracker.AddStock("SKU-100", 25);
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-100"));
    }

    [TestMethod]
    public void AddStock_MultipleCalls_Accumulates()
    {
        _tracker.AddStock("SKU-100", 10);
        _tracker.AddStock("SKU-100", 15);
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-100"));
    }

    [TestMethod]
    public void AddStock_DifferentSkus_TrackedIndependently()
    {
        _tracker.AddStock("SKU-A", 5);
        _tracker.AddStock("SKU-B", 12);

        Assert.AreEqual(5, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    public void RemoveStock_SufficientInventory_DecreasesLevel()
    {
        _tracker.AddStock("SKU-100", 20);
        _tracker.RemoveStock("SKU-100", 8);
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-100"));
    }

    [TestMethod]
    public void RemoveStock_ExactAmount_LeavesZero()
    {
        _tracker.AddStock("SKU-100", 10);
        _tracker.RemoveStock("SKU-100", 10);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-100"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientInventory_ThrowsInvalidOperation()
    {
        _tracker.AddStock("SKU-100", 5);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-100", 10));
    }

    [TestMethod]
    public void RemoveStock_FromUnknownSku_ThrowsInvalidOperation()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("GHOST", 1));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void AddStock_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.AddStock(sku!, 1));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void AddStock_NonPositiveQuantity_ThrowsArgumentOutOfRange(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-100", qty));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void GetStockLevel_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));
    }
}

[TestClass]
public sealed class ReorderAlertTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    [TestMethod]
    public void NeedsReorder_StockBelowDefaultThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-100", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-100"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtDefaultThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-100", 10);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-100"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveDefaultThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-100", 50);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-100"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        // Zero stock is below default threshold of 10
        Assert.IsTrue(_tracker.NeedsReorder("NEVER-ADDED"));
    }

    [TestMethod]
    public void NeedsReorder_CustomThresholdPerSku()
    {
        _tracker.SetReorderThreshold("SKU-100", 3);
        _tracker.AddStock("SKU-100", 5);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-100"));
    }

    [TestMethod]
    public void NeedsReorder_CustomThresholdDoesNotAffectOtherSkus()
    {
        _tracker.SetReorderThreshold("SKU-A", 3);
        _tracker.AddStock("SKU-A", 5);
        _tracker.AddStock("SKU-B", 5);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-A")); // custom threshold 3
        Assert.IsTrue(_tracker.NeedsReorder("SKU-B"));  // default threshold 10
    }

    [TestMethod]
    public void NeedsReorder_AfterRemovingStock_UpdatesCorrectly()
    {
        _tracker.AddStock("SKU-100", 50);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-100"));

        _tracker.RemoveStock("SKU-100", 45);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-100"));
    }

    [TestMethod]
    public void ReorderThreshold_DefaultValueIsTen()
    {
        Assert.AreEqual(10, _tracker.ReorderThreshold);
    }

    [TestMethod]
    public void ReorderThreshold_CanBeChangedGlobally()
    {
        _tracker.ReorderThreshold = 20;
        _tracker.AddStock("SKU-100", 15);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-100"));
    }

    [TestMethod]
    public void SetReorderThreshold_NegativeValue_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.SetReorderThreshold("SKU-100", -1));
    }
}

[TestClass]
public sealed class WarehouseTransferTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup()
    {
        _tracker = new InventoryTracker();
        _tracker.AddStock("SKU-100", 30);
        _tracker.AssignWarehouse("SKU-100", "WH-EAST");
    }

    [TestMethod]
    public void TransferStock_ValidTransfer_ChangesWarehouseAssignment()
    {
        _tracker.TransferStock("SKU-100", 10, "WH-EAST", "WH-WEST");
        Assert.AreEqual("WH-WEST", _tracker.GetWarehouse("SKU-100"));
    }

    [TestMethod]
    public void TransferStock_ValidTransfer_PreservesStockLevel()
    {
        _tracker.TransferStock("SKU-100", 10, "WH-EAST", "WH-WEST");
        Assert.AreEqual(30, _tracker.GetStockLevel("SKU-100"));
    }

    [TestMethod]
    public void TransferStock_SameWarehouse_ThrowsInvalidOperation()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-100", 5, "WH-EAST", "WH-EAST"));
    }

    [TestMethod]
    public void TransferStock_WrongSourceWarehouse_ThrowsInvalidOperation()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-100", 5, "WH-NORTH", "WH-WEST"));
    }

    [TestMethod]
    public void TransferStock_InsufficientStock_ThrowsInvalidOperation()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-100", 100, "WH-EAST", "WH-WEST"));
    }

    [TestMethod]
    public void TransferStock_UnassignedSku_ThrowsInvalidOperation()
    {
        _tracker.AddStock("SKU-NEW", 10);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-NEW", 5, "WH-EAST", "WH-WEST"));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void TransferStock_NonPositiveQuantity_ThrowsArgumentOutOfRange(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.TransferStock("SKU-100", qty, "WH-EAST", "WH-WEST"));
    }

    [TestMethod]
    public void AssignWarehouse_ThenGetWarehouse_ReturnsAssignment()
    {
        Assert.AreEqual("WH-EAST", _tracker.GetWarehouse("SKU-100"));
    }

    [TestMethod]
    public void GetWarehouse_UnassignedSku_ReturnsNull()
    {
        Assert.IsNull(_tracker.GetWarehouse("UNASSIGNED"));
    }

    [TestMethod]
    public void AssignWarehouse_Reassign_OverwritesPrevious()
    {
        _tracker.AssignWarehouse("SKU-100", "WH-SOUTH");
        Assert.AreEqual("WH-SOUTH", _tracker.GetWarehouse("SKU-100"));
    }
}

